import{STARTERS,POKEMON_NAMES,ITEMS,SHOP,ALL_WILD_POOL as WILD_POOL,ALL_WILD_SPECIES as WILD_SPECIES,LEADERS,FIXED_MISSIONS,DAILY_MISSION_TYPES,GAME_COSTS,sprite,shinySprite,itemSprite,coinSprite,furnitureSprite,typeSprite}from'./data.js';
