let state=load(),selected=null,currentView='home',battle=null,toastTimer,shopFilter='all',missionFilter='fixed',titleFilter='Todos',furnitureEditing=false,homeObserver=null;
function normalizeState(){if(!state)return;state.storedFurniture=state.storedFurniture||[];state.redeemedCodes=state.redeemedCodes||[];state.trainerTitle=state.trainerTitle||null;state.rescueCenter=state.rescueCenter||[];state.expeditionHistory=state.expeditionHistory||[];state.eventStats=state.eventStats||{rescued:0,greatSuccess:0,collections:{},labTypes:[]};state.eventStats.collections=state.eventStats.collections||{};state.eventStats.labTypes=state.eventStats.labTypes||[];state.badges=Array.isArray(state.badges)?[...new Set(state.badges.map(Number).filter(i=>Number.isInteger(i)&&i>=0&&i<LEADERS.length))]:[];const oldFixed=state.fixedMissions||[],oldBrock=oldFixed.find(m=>m.id==='fixed-brock');if((oldBrock?.progress>=oldBrock?.target||oldBrock?.claimed)&&!state.badges.includes(0))state.badges.push(0);state.badges.sort((a,b)=>a-b);const owned=Math.max(0,(state.active?.length||0)+(state.boxes?.length||0)-1),oldWins=oldFixed.find(m=>m.id==='fixed-trainers-3')?.progress||0;state.missionStats={captures:Math.max(owned,state.missionStats?.captures||0),battleWins:Math.max(oldWins,state.missionStats?.battleWins||0),npcWins:state.missionStats?.npcWins||0,food:state.missionStats?.food||0,play:state.missionStats?.play||0,games:state.missionStats?.games||0};state.fixedMissions=FIXED_MISSIONS.map(template=>{const old=oldFixed.find(m=>m.id===template.id),key=template.kind==='captureAny'?'captures':'battleWins',progress=Math.min(template.target,state.missionStats[key]||0);return{...template,progress,claimed:!!old?.claimed}});state.gymMissions=LEADERS.map((leader,i)=>{const old=state.gymMissions?.find(m=>m.id===`gym-${i}`);return{id:`gym-${i}`,title:`Desafio de ${leader.name}`,desc:`Derrote ${leader.name} e conquiste a Insígnia ${leader.badge}.`,kind:'gym',gym:i,target:1,progress:state.badges.includes(i)?1:0,claimed:!!old?.claimed,reward:{coins:350+i*200,xp:150+i*100,items:{[i<2?'great-ball':i<7?'ultra-ball':'max-potion']:3+i}}}});state.dailyMissionHistory=state.dailyMissionHistory||[];for(const p of [...(state.active||[]),...(state.boxes||[])])p.friendship=Number.isFinite(p.friendship)?p.friendship:70}
normalizeState();
const $=s=>document.querySelector(s),clamp=n=>Math.max(0,Math.min(100,n)),fmt=s=>s.split('-').map(x=>x[0].toUpperCase()+x.slice(1)).join(' '),spriteFor=p=>p?.shiny?shinySprite(p.id):sprite(p.id);
const typeIcons=(types=[])=>`<span class="type-icons">${types.filter(Boolean).map(type=>`<img src="${typeSprite(type)}" alt="Tipo ${TYPE_LABELS[type]||fmt(type)}" title="${TYPE_LABELS[type]||fmt(type)}">`).join('')}</span>`;
const itemImg=(id,alt='')=>`<img class="item-pixel" src="${itemSprite(id)}" alt="${alt}">`;
const rarityLabel=e=>({comum:'Comum',incomum:'Incomum',raro:'Raro','muito-raro':'Muito raro'}[e.tier]||'Comum');
async function playCry(id){if(!state?.soundEnabled)return;try{const d=await pokemon(id);if(d.cry){const a=new Audio(d.cry);a.volume=.28;await a.play()}}catch{}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function persist(){save(state);updateResources()}
function updateResources(){if(!state)return;$('#coins-value').textContent=Math.floor(state.coins);$('#balls-value').textContent=['poke-ball','great-ball','ultra-ball','master-ball'].reduce((n,id)=>n+(state.inventory[id]||0),0)}
function dailyMissionPool(){const typeNames={normal:'Normal',fire:'Fogo',water:'Água',grass:'Planta',electric:'Elétrico',ice:'Gelo',fighting:'Lutador',poison:'Venenoso',ground:'Terrestre',flying:'Voador',psychic:'Psíquico',bug:'Inseto',rock:'Pedra',ghost:'Fantasma',dragon:'Dragão',dark:'Sombrio',steel:'Aço',fairy:'Fada'},pool=[];for(const type of DAILY_MISSION_TYPES){const target=2+Math.floor(Math.random()*3);pool.push({id:`daily-capture-${type}-${target}`,title:`Pesquisa: ${typeNames[type]}`,desc:`Capture ${target} Pokémon do tipo ${typeNames[type]}.`,kind:'captureType',type,target,reward:{coins:160+target*45,xp:60+target*25,items:{[ITEMS.find(i=>i.type==='food'&&i.favored?.includes(type))?.id||'oran-berry']:target}}})}for(const target of[2,3,5])pool.push({id:`daily-npc-${target}`,title:'Duelo com treinadores',desc:`Vença ${target} batalhas contra treinadores visitantes.`,kind:'npcWin',target,reward:{coins:180+target*80,xp:80+target*35,items:{'great-ball':target}}});for(const target of[2,4,6])pool.push({id:`daily-food-${target}`,title:'Hora do lanche',desc:`Alimente seu Pokémon ${target} vezes.`,kind:'food',target,reward:{coins:120+target*35,items:{'sitrus-berry':Math.ceil(target/2)}}});for(const target of[2,4,6])pool.push({id:`daily-play-${target}`,title:'Parceiros de brincadeira',desc:`Brinque com seu Pokémon ${target} vezes.`,kind:'play',target,reward:{coins:120+target*35,xp:target*25,items:{'poke-doll':1}}});for(const target of[2,3,5])pool.push({id:`daily-games-${target}`,title:'Treino no arcade',desc:`Vença ${target} minigames.`,kind:'game',target,reward:{coins:160+target*55,xp:80+target*40,items:{'great-ball':target}}});return pool}
function ensureDailyMissions(){const today=new Date().toDateString(),valid=state.dailyMissions?.schema===2&&state.dailyMissions?.date===today&&!state.dailyMissions.missions.some(m=>m.kind==='gym');if(valid)return;const previous=state.dailyMissions?.missions?.map(m=>m.id)||state.dailyMissionHistory||[],pool=dailyMissionPool(),available=pool.filter(m=>!previous.includes(m.id));for(let i=available.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[available[i],available[j]]=[available[j],available[i]]}const chosen=[],kinds=new Set;for(const m of available){if(!kinds.has(m.kind)){chosen.push(m);kinds.add(m.kind)}if(chosen.length===5)break}if(chosen.length<5)chosen.push(...available.filter(m=>!chosen.includes(m)).slice(0,5-chosen.length));state.dailyMissionHistory=previous;state.dailyMissions={schema:2,date:today,missions:chosen.map(m=>({...m,progress:0,claimed:false}))};persist()}
function progressMissions(kind,payload={}){ensureDailyMissions();const statKey={captureAny:'captures',battleWin:'battleWins',npcWin:'npcWins',food:'food',play:'play',game:'games'}[kind];if(statKey)state.missionStats[statKey]=(state.missionStats[statKey]||0)+1;for(const m of state.fixedMissions){const key=m.kind==='captureAny'?'captures':'battleWins';m.progress=Math.min(m.target,state.missionStats[key]||0)}if(kind==='gym')for(const m of state.gymMissions)if(m.gym===payload.gym)m.progress=1;for(const m of state.dailyMissions.missions){if(m.claimed||m.progress>=m.target||m.kind!==kind)continue;if(kind==='captureType'&&!payload.types?.includes(m.type))continue;m.progress=Math.min(m.target,m.progress+1)}persist()}
function rewardText(r){const parts=[];if(r.coins)parts.push(`${r.coins} PC`);if(r.xp)parts.push(`${r.xp} XP`);for(const[id,q]of Object.entries(r.items||{}))parts.push(`${q}× ${ITEMS.find(i=>i.id===id)?.name||id}`);return parts.join(' · ')}
function claimMission(id){const m=[...state.fixedMissions,...state.gymMissions,...state.dailyMissions.missions].find(x=>x.id===id);if(!m||m.claimed||m.progress<m.target)return;state.coins+=m.reward.coins||0;if(m.reward.xp)gainXp(m.reward.xp);for(const[id,q]of Object.entries(m.reward.items||{}))state.inventory[id]=(state.inventory[id]||0)+q;m.claimed=true;persist();missionsView();toast(`Missão concluída! ${rewardText(m.reward)}`)}
function missionCard(m){return`<article class="mission-card ${m.claimed?'claimed':m.progress>=m.target?'complete':''}"><div><h3>${m.title}</h3><p>${m.desc}</p></div><div class="mission-progress"><span style="width:${clamp(m.progress/m.target*100)}%"></span></div><small>${m.progress}/${m.target}</small><p class="mission-reward">${rewardText(m.reward)}</p><button data-claim-mission="${m.id}" ${m.claimed||m.progress<m.target?'disabled':''}>${m.claimed?'Resgatada':m.progress>=m.target?'Resgatar':'Em andamento'}</button></article>`}
function missionsView(){ensureDailyMissions();const groups={fixed:state.fixedMissions,gyms:state.gymMissions,daily:state.dailyMissions.missions},titles={fixed:'Missões fixas',gyms:'Desafios de ginásio',daily:'Missões diárias'};$('#view-container').innerHTML=`<div class="view-title"><div><h1>Missões</h1><p>Objetivos permanentes, desafios de Kanto e pesquisas renovadas diariamente.</p></div><span>${state.dailyMissions.date}</span></div><div class="mission-tabs">${[['fixed','Fixas'],['gyms','Ginásios'],['daily','Diárias']].map(([id,label])=>`<button class="${missionFilter===id?'active':''}" data-mission-filter="${id}">${label}</button>`).join('')}</div><h2 class="section-label">${titles[missionFilter]}</h2><div class="mission-grid">${groups[missionFilter].map(missionCard).join('')}</div>`;$('#view-container').onclick=e=>{const tab=e.target.closest('[data-mission-filter]'),b=e.target.closest('[data-claim-mission]');if(tab){missionFilter=tab.dataset.missionFilter;return missionsView()}if(b)claimMission(b.dataset.claimMission)}}
function requestTrainerName(){const m=$('#modal');$('#modal-content').innerHTML=`<h2>Identidade do treinador</h2><p>Como devemos chamar você nesta jornada?</p><label class="name-field">Nome do treinador<input id="legacy-trainer-name" maxlength="16" placeholder="Seu nome"></label><button class="primary-button" id="save-trainer-name" disabled>Salvar nome</button>`;m.showModal();const input=$('#legacy-trainer-name'),button=$('#save-trainer-name');input.oninput=()=>button.disabled=!input.value.trim();button.onclick=()=>{state.trainerName=input.value.trim();persist();m.close();home();toast(`Bem-vindo, ${state.trainerName}!`)}}
function setupPersonalization(){homeObserver?.disconnect();const root=$('#view-container');homeObserver=new MutationObserver(()=>{if(currentView!=='home')return;const h=root.querySelector('.view-title h1');if(!h)return;const greeting=`Olá, ${state.trainerName||'treinador'}!`;if(h.textContent!==greeting)h.textContent=greeting;let title=root.querySelector('.equipped-title');if(state.trainerTitle&&!title){title=document.createElement('strong');title.className='equipped-title';h.after(title)}if(title&&title.textContent!==(state.trainerTitle||''))title.textContent=state.trainerTitle||''});homeObserver.observe(root,{childList:true,subtree:true})}
async function hydrateOwnedTypes(){const missing=ownedPokemon().filter(p=>!Array.isArray(p.types));if(!missing.length)return;await Promise.all(missing.map(async p=>{try{p.types=(await pokemon(p.id)).types}catch{p.types=[]}}));persist()}
async function profileView(){const root=$('#view-container');root.innerHTML='<div class="panel"><h2>Carregando perfil do treinador...</h2></div>';await hydrateOwnedTypes();if(currentView!=='profile')return;const owned=ownedPokemon(),titles=ALL_TITLES().map(t=>({...t,...titleProgress(t,state,owned)})),categories=['Todos',...new Set(titles.map(t=>t.category))],visible=titleFilter==='Todos'?titles:titles.filter(t=>t.category===titleFilter),unlocked=titles.filter(t=>t.value>=t.target);root.innerHTML=`<div class="view-title"><div><h1>${state.trainerName||'Treinador'}</h1><strong class="equipped-title">${state.trainerTitle||'Sem título equipado'}</strong><p>${state.caught.length} espécies · ${state.badges.length} insígnias · ${unlocked.length} títulos</p></div><button class="secondary-button" id="rename-trainer">Alterar nome</button></div><div class="title-filters">${categories.map(c=>`<button class="${titleFilter===c?'active':''}" data-title-filter="${c}">${c}</button>`).join('')}</div><div class="title-grid"><article class="title-card unlocked ${!state.trainerTitle?'equipped':''}"><h3>Sem título</h3><p>Exiba apenas seu nome.</p><button data-equip-title="">${!state.trainerTitle?'Equipado':'Equipar'}</button></article>${visible.map(t=>`<article class="title-card ${t.value>=t.target?'unlocked':'locked'} ${state.trainerTitle===t.name?'equipped':''}"><small>${t.category}</small><h3>${t.name}</h3><p>${t.description}</p><div class="mission-progress"><span style="width:${clamp(t.value/t.target*100)}%"></span></div><b>${t.value}/${t.target}</b><button data-equip-title="${t.id}" ${t.value<t.target?'disabled':''}>${state.trainerTitle===t.name?'Equipado':'Equipar'}</button></article>`).join('')}</div>`;root.onclick=e=>{const filter=e.target.closest('[data-title-filter]'),equip=e.target.closest('[data-equip-title]');if(filter){titleFilter=filter.dataset.titleFilter;return profileView()}if(equip){const chosen=titles.find(t=>t.id===equip.dataset.equipTitle);if(chosen&&chosen.value<chosen.target)return;state.trainerTitle=chosen?.name||null;persist();profileView();toast(chosen?`Título equipado: ${chosen.name}`:'Título removido.')}};$('#rename-trainer').onclick=()=>{const name=prompt('Novo nome do treinador:',state.trainerName||'')?.trim();if(name){state.trainerName=name.slice(0,16);persist();profileView()}}}
function starters(){const grid=$('#starter-grid');grid.innerHTML=STARTERS.map(id=>`<button class="starter-card" data-id="${id}"><img src="${sprite(id)}" alt=""><b>${POKEMON_NAMES[id]}</b></button>`).join('');const validate=()=>$('#start-button').disabled=!selected||!$('#trainer-name-input').value.trim();$('#trainer-name-input').oninput=validate;grid.onclick=e=>{const c=e.target.closest('.starter-card');if(!c)return;selected=+c.dataset.id;grid.querySelectorAll('.starter-card').forEach(x=>x.classList.toggle('selected',x===c));$('#starter-count').textContent=`${STARTERS.indexOf(selected)+1} / 11`;$('#nickname-input').placeholder=POKEMON_NAMES[selected];validate()};$('#start-button').onclick=()=>{const name=$('#nickname-input').value.trim()||POKEMON_NAMES[selected],trainer=$('#trainer-name-input').value.trim();state=fresh(selected,name,POKEMON_NAMES[selected],trainer);persist();enterGame();toast(`Bem-vindo ao Pokégotchi, ${trainer}!`)}}
function showTitle(){const has=!!state,p=state?.pokemon;$('#title-screen').classList.remove('hidden');$('#starter-screen').classList.add('hidden');$('#game-screen').classList.add('hidden');$('#continue-button').disabled=!has;$('#save-summary').textContent=has?`${p.nickname} · ${p.name} · Nv. ${p.level} · ${state.caught.length} espécies`:'Nenhuma jornada encontrada.';$('#continue-button').onclick=()=>enterGame();$('#changelog-button').onclick=showChangelog;$('#new-game-button').onclick=()=>{if(state&&!confirm('Começar uma nova jornada apagará permanentemente o save atual. Deseja continuar?'))return;if(state)clear();state=null;selected=null;$('#title-screen').classList.add('hidden');$('#starter-screen').classList.remove('hidden');starters()}}
function enterGame(){const mins=applyOffline(state);$('#title-screen').classList.add('hidden');$('#starter-screen').classList.add('hidden');$('#game-screen').classList.remove('hidden');setupNav();setupPersonalization();updateResources();generateOfflineEncounters();render(currentView);if(!state.trainerName)setTimeout(requestTrainerName,200);else if(mins)toast(`Enquanto você saiu, ${mins} min se passaram.`);updateWeather()}
function setupNav(){$('.sidebar')?.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;currentView=b.dataset.view;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n===b));render(currentView)});$('#settings-button').onclick=settings;$('#help-button').onclick=showHelp}
function render(v){normalizeState();ensureDailyMissions();generateOfflineEncounters();({home,profile:profileView,yard,events:eventsView,games,missions:missionsView,shop,inventory,codes:codesView,rooms,furniture:furnitureView,status:statusView,dex,battle:battleView}[v]||home)();updateResources()}
function stat(icon,label,value,color){return`<div class="stat-row"><span class="pixel-label">${icon}</span><span>${label}</span><div class="stat-track"><div class="stat-fill" style="width:${clamp(value)}%;background:${color}"></div></div><b>${Math.round(value)}</b></div>`}
function weatherMark(){return`<span class="weather-mark ${state.weather.icon}">${state.weather.icon==='rain'?'///':state.weather.icon==='storm'?'ZAP':state.weather.icon==='cloudy'?'CLOUD':state.weather.icon==='snow'?'***':'SUN'}</span>`}
function furnitureLayer(){return state.furniture.map((id,i)=>{const pos=state.furniturePositions?.[id]||{x:4+(i%6)*15,y:i<2?66:72};return`<img class="furniture-sprite furniture-${id}" data-furniture="${id}" style="left:${pos.x}%;top:${pos.y}%" src="${furnitureSprite(id)}" alt="${ITEMS.find(x=>x.id===id)?.name||id}">`}).join('')}
const badgeSprite=i=>`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/badges/${i+1}.png`;
function badgeCase(){return`<section class="badge-case" aria-label="Estojo de insígnias de Kanto"><span>INSÍGNIAS</span><div>${LEADERS.map((leader,i)=>`<figure class="badge-slot ${state.badges.includes(i)?'earned':'locked'}" title="${state.badges.includes(i)?`Insígnia ${leader.badge} · ${leader.name}`:`??? · Derrote ${leader.name}`}"><img src="${badgeSprite(i)}" alt="${state.badges.includes(i)?`Insígnia ${leader.badge}`:'Insígnia ainda não conquistada'}"><figcaption>${i+1}</figcaption></figure>`).join('')}</div></section>`}
function home(){const p=state.pokemon,w=state.weather,sleeping=!!p.sleepingSince,need=sleeping?'Z Z Z...':p.hunger<35?'Estou com fome!':p.energy<30?'Preciso dormir...':p.happiness<35?'Vamos brincar?':'Que bom ver você!';$('#view-container').innerHTML=`<div class="view-title"><div><h1>Olá, treinador!</h1><p>Seu parceiro está ${sleeping?'descansando':'feliz em ver você'}.</p></div><span>${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</span></div><div class="home-grid"><div class="room-column"><div class="room ${w.day?'':'night'} ${furnitureEditing?'editing-furniture':''}"><div class="weather-badge">${weatherMark()} ${w.label}${w.temp!==null?' · '+w.temp+'°C':''}</div>${state.furniture.length?`<button class="organize-button" id="organize-furniture">${furnitureEditing?'Concluir':'Mover móveis'}</button>`:''}<div class="furniture-layer">${furnitureLayer()}</div><div class="pet-stage"><div class="pet-bubble">${need}</div><img class="pet-sprite ${sleeping?'sleeping':''}" src="${spriteFor(p)}" alt="${p.nickname}"><div class="pet-shadow"></div></div><div class="room-actions"><button class="action-button" data-act="food">${itemImg('oran-berry')}Alimentar</button><button class="action-button" data-act="play">${itemImg('poke-doll')}Brincar</button><button class="action-button" data-act="sleep">${itemImg('leftovers')}${sleeping?'Acordar':'Dormir'}</button><button class="action-button" data-act="clean">${itemImg('rage-candy-bar')}Limpar</button></div></div>${badgeCase()}</div><div class="side-stack"><div class="profile-card"><div class="pet-id"><div><small>${p.shiny?'★ SHINY · ':''}${p.name.toUpperCase()}</small><h2>${p.nickname}</h2></div><span class="level-pill">NV. ${p.level}</span></div><small>${p.xp} / ${p.level*45} XP</small><div class="xp-track"><div class="xp-fill" style="width:${p.xp/(p.level*45)*100}%"></div></div><div class="stats">${stat('HP','Saúde',p.health,'#df3f47')}${stat('FO','Fome',p.hunger,'#d19b43')}${stat('EN','Energia',p.energy,'#3e80b6')}${stat('FE','Felicidade',p.happiness,'#a65fc0')}${stat('HI','Higiene',p.hygiene,'#62a84c')}</div>${sleeping?`<div class="sleep-note">Carga completa em aproximadamente ${sleepRemaining(p)}${state.furniture.includes('soft-bed')?' com a cama melhorada':''}.</div>`:''}</div><div class="daily-note"><h3>Presente diário</h3><p>PokéCoins e um item surpresa por dia.</p><button id="daily">Resgatar presente</button></div></div></div>`;$('#view-container').onclick=e=>{const a=e.target.closest('[data-act]');if(a&&!furnitureEditing)care(a.dataset.act)};$('#daily').onclick=daily;$('#organize-furniture')?.addEventListener('click',()=>{furnitureEditing=!furnitureEditing;home()});if(furnitureEditing)enableFurnitureDrag()}
function enableFurnitureDrag(){const room=$('.room');room.querySelectorAll('[data-furniture]').forEach(el=>{el.onpointerdown=ev=>{ev.preventDefault();el.setPointerCapture(ev.pointerId);const move=e=>{const r=room.getBoundingClientRect(),x=clamp((e.clientX-r.left)/r.width*100),y=clamp((e.clientY-r.top)/r.height*100);el.style.left=`${Math.min(88,Math.max(0,x-6))}%`;el.style.top=`${Math.min(78,Math.max(8,y-8))}%`};el.onpointermove=move;el.onpointerup=e=>{el.releasePointerCapture(e.pointerId);el.onpointermove=null;const r=room.getBoundingClientRect();state.furniturePositions[el.dataset.furniture]={x:parseFloat(el.style.left),y:parseFloat(el.style.top)};persist();toast('Posição do móvel salva.')}}})}
function sleepRemaining(p){const perPoint=(state.furniture.includes('soft-bed')?144000:288000),left=Math.max(0,(100-p.energy)*perPoint),h=Math.floor(left/3600000),m=Math.ceil(left%3600000/60000);return`${h}h ${m}min`}
function updateSleepTimer(){const p=state?.pokemon;if(!p?.sleepingSince)return;const note=$('.sleep-note');if(!note)return;const improved=state.furniture.includes('soft-bed'),fullMs=improved?14400000:28800000,start=Number.isFinite(p.sleepEnergyStart)?p.sleepEnergyStart:p.energy,target=p.sleepingSince+(100-start)/100*fullMs,left=Math.max(0,target-Date.now()),seconds=Math.ceil(left/1000),h=String(Math.floor(seconds/3600)).padStart(2,'0'),m=String(Math.floor(seconds%3600/60)).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');note.innerHTML=left>0?`Carga completa em <b>${h}:${m}:${s}</b>${improved?' com a cama melhorada':''}.`:'<b>Energia completamente recuperada!</b>'}
function care(type){const p=state.pokemon;if(onExpedition(p))return toast(`${p.nickname} está em expedição.`);if(type==='sleep'){if(p.sleepingSince){applyOffline(state);p.sleepingSince=null;p.sleepEnergyStart=null;toast(`${p.nickname} acordou com ${Math.round(p.energy)} de energia.`)}else{p.sleepingSince=Date.now();p.sleepEnergyStart=p.energy;toast(`${p.nickname} começou a dormir. Energia cheia em até ${state.furniture.includes('soft-bed')?'4h':'8h'}.`)}persist();return home()}if(p.sleepingSince)return toast('Acorde seu Pokémon primeiro.');openItemPicker(type)}
