const resultName=r=>({severe:'Fracasso grave',failure:'Fracasso',partial:'Sucesso parcial',success:'Sucesso',great:'Grande sucesso'}[r]||r);
const randomLoss=([a,b])=>a+Math.random()*(b-a);
function collectExpedition(){const exp=state.expedition;if(!exp||Date.now()<exp.endAt)return;const p=findOwned(exp.pokemonUid),losses={severe:{health:[60,90],energy:[70,95],hunger:[35,55],happiness:[20,35],friendship:-3},failure:{health:[25,45],energy:[45,70],hunger:[25,40],happiness:[10,20],friendship:-1},partial:{health:[10,25],energy:[35,55],hunger:[20,35],happiness:[5,10],friendship:2},success:{health:[5,15],energy:[25,45],hunger:[15,30],happiness:[0,5],friendship:4},great:{health:[0,10],energy:[20,35],hunger:[15,25],happiness:[0,2],friendship:7}}[exp.result];if(p){p.health=Math.max(10,p.health-randomLoss(losses.health));p.energy=clamp(p.energy-randomLoss(losses.energy));p.hunger=clamp(p.hunger-randomLoss(losses.hunger));p.happiness=exp.result==='great'||exp.result==='success'?clamp(p.happiness+randomLoss(losses.happiness)):clamp(p.happiness-randomLoss(losses.happiness));p.friendship=clamp((p.friendship??70)+losses.friendship)}const room=Math.max(0,20-state.rescueCenter.length),rescues=exp.rescues.slice(0,room);state.rescueCenter.push(...rescues);state.eventStats.rescued+=rescues.length;if(exp.result==='great')state.eventStats.greatSuccess++;state.expeditionHistory.push({eventId:exp.eventId,pokemonName:exp.pokemonName,chance:exp.chance,result:exp.result,rescued:rescues.length,finishedAt:Date.now()});const result=exp.result;state.expedition=null;persist();eventsView();toast(`${resultName(result)}! ${rescues.length} Pokémon resgatados.`)}
async function openRescueCapture(rescueId){const e=state.rescueCenter.find(r=>r.rescueId===rescueId);if(!e)return;try{const info=await pokemon(e.id);e.name=info.name;e.types=info.types;e.baseCatch=info.rarity;persist();drawRescueCapture(e);playCry(e.id)}catch{toast('Não foi possível abrir este resgate.')}}
function drawRescueCapture(e){const berries=ITEMS.filter(i=>i.type==='food'&&(state.inventory[i.id]||0)),balls=ITEMS.filter(i=>i.type==='ball'&&(state.inventory[i.id]||0));e.selectedBall=e.selectedBall&&state.inventory[e.selectedBall]?e.selectedBall:balls[0]?.id||null;const chance=e.selectedBall?captureChance(e,e.selectedBall):0;$('#view-container').innerHTML=`<div class="view-title"><div><h1>Centro de Resgate</h1><p>${e.shiny?'★ SHINY · ':''}${e.name} · ${e.types.map(fmt).join(' / ')}</p></div><button class="secondary-button" id="back-rescue">Voltar</button></div><div class="capture-layout"><div class="yard-scene capture-scene"><div class="wild-card"><div class="capture-ring ${chanceClass(chance)}"><span>${Math.round(chance*100)}%</span></div><img class="wild-sprite ${e.shiny?'shiny-sparkle':''}" src="${spriteFor(e)}" alt="${e.name}"><h2>${e.shiny?'★ ':''}${e.name}</h2><p>${e.fed?'Berry oferecida.':'Este Pokémon resgatado não fugirá.'}</p></div><div class="ball-tray">${balls.map(i=>`<button class="${e.selectedBall===i.id?'selected':''}" data-select-rescue-ball="${i.id}">${itemImg(i.id)}<small>×${state.inventory[i.id]}</small></button>`).join('')||'<span>Sem Pokébolas</span>'}</div></div><div class="capture-tools"><div class="panel"><h3>Berries</h3><div class="tool-row">${berries.map(i=>`<button data-feed-rescue="${i.id}" ${e.fed?'disabled':''}>${itemImg(i.id)}<small>${i.favored.some(t=>e.types.includes(t))?'EFETIVA · ':''}×${state.inventory[i.id]}</small></button>`).join('')||'Sem berries'}</div></div><div class="panel capture-feedback ${chanceClass(chance)}"><h3>Chance de captura</h3><b>${Math.round(chance*100)}%</b></div><button class="primary-button" id="throw-rescue" ${!e.selectedBall?'disabled':''}>Lançar Pokébola</button></div></div>`;$('#view-container').onclick=ev=>{const f=ev.target.closest('[data-feed-rescue]'),b=ev.target.closest('[data-select-rescue-ball]');if(f&&state.inventory[f.dataset.feedRescue]){state.inventory[f.dataset.feedRescue]--;e.fed=f.dataset.feedRescue;persist();drawRescueCapture(e)}if(b){e.selectedBall=b.dataset.selectRescueBall;drawRescueCapture(e)}};$('#throw-rescue').onclick=()=>throwRescueBall(e,e.selectedBall);$('#back-rescue').onclick=eventsView}
async function throwRescueBall(e,id){const ball=ITEMS.find(i=>i.id===id);if(!ball||!state.inventory[id])return;state.inventory[id]--;const chance=captureChance(e,id);persist();$('.capture-scene')?.classList.add('throwing');await new Promise(r=>setTimeout(r,1200));if(Math.random()<chance)nicknameRescue(e);else{toast(`${e.name} saiu da bola, mas continua no Centro de Resgate.`);drawRescueCapture(e)}}
function nicknameRescue(e){const m=$('#modal');$('#modal-content').innerHTML=`<div class="capture-success ${e.shiny?'shiny-card':''}"><img src="${spriteFor(e)}" alt=""><h2>${e.name} foi capturado!</h2><label class="name-field">Apelido<input id="rescue-nickname" maxlength="14" value="${e.name}"></label><button class="primary-button" id="confirm-rescue-name">Confirmar</button></div>`;m.showModal();$('#confirm-rescue-name').onclick=()=>{const p=addCreature(state,e,$('#rescue-nickname').value.trim()||e.name);progressMissions('captureAny');progressMissions('captureType',{types:e.types});state.eventStats.collections[e.eventId]=[...new Set([...(state.eventStats.collections[e.eventId]||[]),e.id])];if(e.eventId==='lab-emergency')state.eventStats.labTypes=[...new Set([...state.eventStats.labTypes,...e.types.filter(t=>['grass','fire','water'].includes(t))])];state.rescueCenter=state.rescueCenter.filter(r=>r.rescueId!==e.rescueId);persist();m.close();eventsView();toast(`${p.nickname} foi enviado para ${state.active.includes(p)?'um quarto':'a Box'}!`)}}
function games(){$('#view-container').innerHTML=`<div class="view-title"><div><h1>Arcade</h1><p>Minigames gastam energia do Pokémon principal.</p></div><span>Energia: ${Math.round(state.pokemon.energy)}</span></div><div class="cards-grid">${[['oran-berry','Pegar Berries','Colete frutas antes que caiam.','berry'],['vs-recorder','Memória Pokémon','Encontre todos os pares.','memory'],['quick-claw','Treino de Ataque','Acerte a faixa verde.','timing']].map(g=>`<article class="game-card"><div class="game-icon">${itemImg(g[0])}</div><h3>${g[1]}</h3><p>${g[2]}</p><b>Custo: ${GAME_COSTS[g[3]]} energia</b><button class="secondary-button" data-game="${g[3]}" ${state.pokemon.energy<GAME_COSTS[g[3]]||state.pokemon.sleepingSince||onExpedition(state.pokemon)?'disabled':''}>${onExpedition(state.pokemon)?'Em expedição':state.pokemon.sleepingSince?'Dormindo':'Jogar agora'}</button></article>`).join('')}</div>`;$('#view-container').onclick=e=>{const b=e.target.closest('[data-game]');if(b)openGame(b.dataset.game)}}
function openGame(type){const cost=GAME_COSTS[type],p=state.pokemon;if(onExpedition(p))return toast('Seu Pokémon está em expedição.');if(p.sleepingSince)return toast('Seu Pokémon está dormindo.');if(p.energy<cost)return toast(`Você precisa de ${cost} de energia.`);p.energy-=cost;persist();const m=$('#modal'),root=$('#modal-content'),finish=(xp,coins,msg)=>{gainXp(xp);state.coins+=coins;p.happiness=clamp(p.happiness+8);p.friendship=clamp((p.friendship??70)+2);progressMissions('game');persist();root.innerHTML=`<div class="game-area">${itemImg('nugget')}<h2>${msg}</h2><p>+${xp} XP · +${coins} PokéCoins · +2 amizade · -${cost} energia</p><button class="primary-button" id="game-done">Continuar</button></div>`;$('#game-done').onclick=()=>m.close()};({berry:berryGame,memory:memoryGame,timing:timingGame}[type])(root,finish);m.showModal()}
function gainXp(xp){const p=state.pokemon,bonus=state.furniture.reduce((n,id)=>n+(ITEMS.find(i=>i.id===id)?.expBonus||0),0);if(xp===12)p.friendship=clamp((p.friendship??70)-5);p.xp+=Math.round(xp*(1+bonus));while(p.xp>=p.level*45){p.xp-=p.level*45;p.level++;refreshMoves(p)}}
async function refreshMoves(p){try{const all=await movesFor(p);if(!p.moves?.length)p.moves=all.slice(-4).map(m=>m.name);persist()}catch{}}
function inventory(){$('#view-container').innerHTML=`<div class="view-title"><div><h1>Mochila</h1><p>Consumíveis, Pokébolas e itens especiais.</p></div></div>${state.incenseUntil>Date.now()?`<div class="incense-status">Incenso ativo · ${Math.ceil((state.incenseUntil-Date.now())/60000)} min restantes</div>`:''}<div class="inventory-grid">${ITEMS.filter(i=>(state.inventory[i.id]||0)>0).map(i=>`<article class="inventory-card">${itemImg(i.id,i.name)}<div><h3>${i.name}</h3><p>${i.desc}</p></div><b>×${state.inventory[i.id]}</b>${['utility','heal','evolution'].includes(i.type)?`<button data-use-inventory="${i.id}" ${i.type==='utility'&&state.incenseUntil>Date.now()?'disabled':''}>Usar</button>`:''}</article>`).join('')||'<p>Sua mochila está vazia.</p>'}</div>`;$('#view-container').onclick=e=>{const b=e.target.closest('[data-use-inventory]');if(!b)return;const i=ITEMS.find(x=>x.id===b.dataset.useInventory);i.type==='heal'?useHealing(i):i.type==='evolution'?chooseEvolutionItem(i):useUtility(i.id)}}
function useHealing(i){const p=state.pokemon;if(!state.inventory[i.id])return;if(p.health>=100&&!i.full)return toast(`${p.nickname} já está com a saúde cheia.`);state.inventory[i.id]--;p.health=clamp(p.health+i.value);if(i.full){p.hunger=100;p.happiness=100;p.hygiene=100}persist();inventory();toast(`${i.name} usada em ${p.nickname}.`)}
function useUtility(id){const i=ITEMS.find(x=>x.id===id);if(!i||!state.inventory[id])return;if(id==='incense'){state.inventory[id]--;state.incenseUntil=Date.now()+i.duration;state.nextSpawn=Date.now()+300000;persist();inventory();toast('Incenso ativado por 1 hora: uma aparição a cada 5 minutos!')}}
function shopCategory(i){return i.type==='food'?'berries':i.type==='evolution'?'evolution':i.type==='furniture'?'furniture':i.type==='heal'?'healing':['ball','utility'].includes(i.type)?'capture':'care'}
function shop(){const filtered=shopFilter==='all'?SHOP:SHOP.filter(i=>shopCategory(i)===shopFilter);$('#view-container').innerHTML=`<div class="view-title"><div><h1>PokéMart</h1><p>Itens oficiais e melhorias para os quartos.</p></div><b><img class="tiny-item" src="${coinSprite}" alt=""> ${Math.floor(state.coins)}</b></div><div class="shop-filters">${[['all','Todos'],['berries','Berries'],['capture','Captura'],['healing','Poções'],['care','Cuidados'],['evolution','Evolução'],['furniture','Móveis']].map(([id,n])=>`<button class="${shopFilter===id?'active':''}" data-filter="${id}">${n}</button>`).join('')}</div><div class="shop-layout"><div class="shop-grid">${filtered.map(i=>`<article class="shop-card">${itemImg(i.id,i.name)}<h3>${i.name}</h3><p>${i.type==='food'?`${i.desc}. Pode alimentar seu Pokémon (+${i.value} fome).`:i.desc}</p><div class="price"><b>${i.price} PC</b><button data-buy="${i.id}">Comprar</button></div></article>`).join('')}</div><aside class="panel"><h3>Resumo</h3><p>${Object.values(state.inventory).reduce((a,b)=>a+b,0)} itens na mochila.</p><p>${state.furniture.length} móveis instalados.</p><p>Bônus de EXP: +${Math.round(state.furniture.reduce((n,id)=>n+(ITEMS.find(i=>i.id===id)?.expBonus||0),0)*100)}%</p></aside></div>`;$('#view-container').onclick=e=>{const f=e.target.closest('[data-filter]'),b=e.target.closest('[data-buy]');if(f){shopFilter=f.dataset.filter;return shop()}if(b)buy(b.dataset.buy)}}
function buy(id){const i=ITEMS.find(x=>x.id===id);if(state.coins<i.price)return toast('PokéCoins insuficientes.');if(i.type==='furniture'&&(state.furniture.includes(id)||state.storedFurniture.includes(id)))return toast('Você já possui esse móvel.');state.coins-=i.price;if(i.type==='furniture')state.furniture.push(id);else state.inventory[id]=(state.inventory[id]||0)+1;persist();shop();toast(`${i.name} adquirido${i.type==='evolution'?' e guardado na Mochila':''}!`)}
function furnitureView(){$('#view-container').innerHTML=`<div class="view-title"><div><h1>Depósito de móveis</h1><p>Guarde um móvel inacessível e coloque-o novamente em uma posição segura.</p></div><span>${state.furniture.length} no quarto</span></div><div class="furniture-manager"><section><h2>Instalados no quarto</h2><div class="furniture-manager-grid">${state.furniture.map(id=>furnitureManagerCard(id,'store')).join('')||'<p>Nenhum móvel instalado.</p>'}</div></section><section><h2>Guardados no depósito</h2><div class="furniture-manager-grid">${state.storedFurniture.map(id=>furnitureManagerCard(id,'place')).join('')||'<p>O depósito está vazio.</p>'}</div></section></div><button class="primary-button" id="move-installed" ${state.furniture.length?'':'disabled'}>Voltar ao quarto e mover</button>`;$('#view-container').onclick=e=>{const b=e.target.closest('[data-furniture-action]');if(!b)return;const id=b.dataset.id;if(b.dataset.furnitureAction==='store'){state.furniture=state.furniture.filter(x=>x!==id);state.storedFurniture.push(id);delete state.furniturePositions[id];toast('Móvel guardado no depósito.')}else{state.storedFurniture=state.storedFurniture.filter(x=>x!==id);state.furniture.push(id);state.furniturePositions[id]={x:40,y:55};toast('Móvel colocado no centro do quarto.')}persist();furnitureView()};$('#move-installed').onclick=()=>{furnitureEditing=true;currentView='home';document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view==='home'));home()}}
function furnitureManagerCard(id,action){const item=ITEMS.find(i=>i.id===id);return`<article><img src="${furnitureSprite(id)}" alt="${item?.name||id}"><b>${item?.name||id}</b><button data-furniture-action="${action}" data-id="${id}">${action==='store'?'Guardar':'Colocar no quarto'}</button></article>`}
function codesView(){$('#view-container').innerHTML=`<div class="view-title"><div><h1>Códigos promocionais</h1><p>Digite um código para receber recompensas especiais. Cada código funciona uma vez por jornada.</p></div><span>${state.redeemedCodes.length} resgatados</span></div><div class="code-terminal"><span>POKÉGOTCHI MYSTERY GIFT</span><label for="promo-code">Código</label><input id="promo-code" maxlength="24" autocomplete="off" spellcheck="false" placeholder="DIGITE O CÓDIGO"><button class="primary-button" id="redeem-code">Resgatar código</button><p id="code-feedback">Os códigos não diferenciam letras maiúsculas e minúsculas.</p></div>`;const input=$('#promo-code');$('#redeem-code').onclick=()=>redeemCode(input.value);input.onkeydown=e=>{if(e.key==='Enter')redeemCode(input.value)};input.focus()}
function redeemCode(raw){const code=raw.trim().toUpperCase(),feedback=$('#code-feedback');if(!code)return feedback.textContent='Digite um código primeiro.';if(state.redeemedCodes.includes(code))return feedback.textContent='Este código já foi resgatado nesta jornada.';if(code==='RELEASE1500'){state.coins+=1500;state.redeemedCodes.push(code);persist();feedback.textContent='Código aceito! Você recebeu 1.500 PokéCoins.';updateResources();return toast('+1.500 PokéCoins!')}if(code==='WELCOME'){const p=addCreature(state,{id:147,name:'Dratini',shiny:true},'Dratini');state.redeemedCodes.push(code);persist();feedback.textContent=`Código aceito! Dratini shiny foi enviado para ${state.active.includes(p)?'um quarto':'a Box'}.`;updateResources();playCry(147);return toast('★ Dratini shiny recebido!')}feedback.textContent='Código inválido ou expirado.'}
function rooms(){$('#view-container').innerHTML=`<div class="view-title"><div><h1>Quartos & Boxes</h1><p>Até seis Pokémon ativos. Abra o status para conferir IV, EV e evolução.</p></div><span>${state.active.length}/6 ativos</span></div><h2 class="section-label">Quartos ativos</h2><div class="rooms-grid">${state.active.map((p,i)=>pokeRoom(p,i)).join('')}${state.active.length<6?`<div class="empty-room">QUARTO LIVRE</div>`:''}</div><h2 class="section-label">Box Pokémon</h2><div class="box-grid">${state.boxes.map((p,i)=>`<article class="box-mon ${p.shiny?'shiny-card':''}"><img src="${spriteFor(p)}" alt="${p.name}"><b>${p.shiny?'★ ':''}${p.nickname}</b><small>Nv. ${p.level}</small><button data-statusuid="${p.uid}">Status</button><button data-box="${i}">Mover ao quarto</button></article>`).join('')||'<p>A Box está vazia.</p>'}</div>`;$('#view-container').onclick=e=>{const status=e.target.closest('[data-statusuid]'),send=e.target.closest('[data-sendbox]'),room=e.target.closest('[data-room]'),box=e.target.closest('[data-box]');if(status)return pokemonStatus(status.dataset.statusuid);if(send)return sendToBox(+send.dataset.sendbox);if(room)return selectPartner(+room.dataset.room);if(box)boxAction(+box.dataset.box)};hydrateRecoveredNames()}
async function hydrateRecoveredNames(){const pending=state.boxes.filter(p=>p.name.startsWith('Pokémon #'));if(!pending.length)return;let changed=false;await Promise.all(pending.map(async p=>{try{const d=await pokemon(p.id);p.name=d.name;p.nickname=d.name;changed=true}catch{}}));if(changed){persist();if(currentView==='rooms')rooms()}}
function pokeRoom(p,i){return`<article class="poke-room ${p.uid===state.pokemon.uid?'primary-room':''} ${p.shiny?'shiny-card':''}"><button data-room="${i}"><span>QUARTO ${i+1}${p.shiny?' · ★ SHINY':''}</span><img src="${spriteFor(p)}" alt="${p.name}"><b>${p.nickname}</b><small>Nv. ${p.level} · EN ${Math.round(p.energy)}</small></button><div class="room-card-actions"><button data-statusuid="${p.uid}">Status</button>${state.active.length>1?`<button class="to-box" data-sendbox="${i}">Enviar à Box</button>`:''}</div></article>`}
const ownedPokemon=()=>[...state.active,...state.boxes];
const findOwned=uid=>ownedPokemon().find(p=>p.uid===uid);
async function statusView(){const root=$('#view-container');root.innerHTML='<div class="panel"><h2>Carregando tipagens...</h2></div>';await hydrateOwnedTypes();if(currentView!=='status')return;root.innerHTML=`<div class="view-title"><div><h1>Status Pokémon</h1><p>Consulte tipo, IV, EV, amizade, evolução e necessidades de cada parceiro.</p></div><span>${ownedPokemon().length} Pokémon</span></div><div class="status-roster">${ownedPokemon().map(p=>`<button class="status-roster-card ${p.shiny?'shiny-card':''}" data-statusuid="${p.uid}"><img src="${spriteFor(p)}" alt="${p.name}"><div><b>${p.shiny?'★ ':''}${p.nickname}</b><span>${p.name} · Nível ${p.level}</span>${typeIcons(p.types)}<small>IV ${p.iv}/31 · EV ${p.ev}/510</small><label>Amizade <b>${Math.round(p.friendship??70)}/100</b></label><span class="friendship-track"><i style="width:${clamp(p.friendship??70)}%"></i></span></div><strong>ABRIR STATUS</strong></button>`).join('')}</div>`;root.onclick=e=>{const b=e.target.closest('[data-statusuid]');if(b)pokemonStatus(b.dataset.statusuid)}}
async function pokemonStatus(uid){const p=findOwned(uid),m=$('#modal');if(!p)return;m.showModal();$('#modal-content').innerHTML=`<h2>Status de ${p.nickname}</h2><p>Consultando dados de evolução...</p>`;let options=[],learned=[];try{[options,learned]=await Promise.all([evolutionOptions(p.id),movesFor(p)])}catch{}const day=state.weather?.day!==false,hasFairy=learned.some(move=>move.type==='fairy'&&(p.moves||[]).includes(move.name)),evaluated=options.map(o=>{const checks=[];if(o.item)checks.push([`Usar ${ITEMS.find(i=>i.id===o.item)?.name||fmt(o.item)}`,false]);if(o.minLevel!==undefined&&o.minLevel!==null)checks.push([`Nível ${o.minLevel}`,p.level>=o.minLevel]);if(o.minHappiness)checks.push([`Amizade ${o.minHappiness}`,p.friendship>=o.minHappiness]);if(o.timeOfDay)checks.push([o.timeOfDay==='day'?'Evoluir durante o dia':'Evoluir durante a noite',o.timeOfDay==='day'?day:!day]);if(o.knownMoveType)checks.push(['Ter um golpe do tipo Fada equipado',hasFairy]);return{...o,checks,ready:!o.item&&checks.every(c=>c[1])}});$('#modal-content').innerHTML=`<div class="pokemon-status-head"><img src="${spriteFor(p)}" alt="${p.name}"><div><h2>${p.shiny?'★ ':''}${p.nickname}</h2><p>${p.name} · Nível ${p.level}</p></div></div><div class="pokemon-status-grid"><div><span>IV geral</span><b>${p.iv}/31</b></div><div><span>EV total</span><b>${p.ev}/510</b></div><div><span>XP</span><b>${p.xp}/${p.level*45}</b></div><div><span>Amizade</span><b>${Math.round(p.friendship??70)}/100</b></div><div><span>Saúde</span><b>${Math.round(p.health)}/100</b></div><div><span>Energia</span><b>${Math.round(p.energy)}/100</b></div><div><span>Felicidade</span><b>${Math.round(p.happiness)}/100</b></div><div><span>Higiene</span><b>${Math.round(p.hygiene)}/100</b></div></div><section class="status-evolution"><h3>Evolução</h3>${evaluated.length?`<div class="evolution-options">${evaluated.map((o,i)=>`<article class="${o.ready?'ready':''}"><img src="${sprite(o.id)}" alt=""><b>${o.name}</b>${o.checks.map(([label,ok])=>`<small class="${ok?'met':'unmet'}">${ok?'✓':'○'} ${label}</small>`).join('')}${o.item?'<em>Use o item pela Mochila.</em>':`<button data-special-evolve="${i}" ${o.ready?'':'disabled'}>Evoluir</button>`}</article>`).join('')}</div>`:'<p>Não há uma próxima evolução registrada.</p>'}</section><section><h3>Golpes escolhidos</h3><p>${p.moves?.join(' · ')||'Nenhum golpe organizado ainda.'}</p></section>`;$('#modal-content').onclick=e=>{const b=e.target.closest('[data-special-evolve]');if(b){const option=evaluated[+b.dataset.specialEvolve];if(option?.ready)performEvolution(p,option)}}}
async function chooseEvolutionItem(item){const m=$('#modal');m.showModal();$('#modal-content').innerHTML=`<h2>Usar ${item.name}</h2><p>Procurando Pokémon compatíveis...</p>`;const matches=[];await Promise.all(ownedPokemon().map(async p=>{try{const options=await evolutionOptions(p.id);for(const option of options)if(option.item===item.id)matches.push({p,option})}catch{}}));$('#modal-content').innerHTML=`<h2>Usar ${item.name}</h2><p>Escolha qual Pokémon receberá o item. Ele só será consumido após a confirmação.</p><div class="evolution-picker">${matches.map(({p,option})=>`<button data-item-evolve="${p.uid}"><img src="${spriteFor(p)}" alt=""><b>${p.nickname}</b><small>${p.name} → ${option.name}</small></button>`).join('')||'<p>Nenhum Pokémon compatível pertence a você.</p>'}</div>`;m.onclick=e=>{const b=e.target.closest('[data-item-evolve]');if(!b)return;const match=matches.find(x=>x.p.uid===b.dataset.itemEvolve);if(!match||!state.inventory[item.id])return;state.inventory[item.id]--;performEvolution(match.p,match.option)}}
async function performEvolution(p,option){const old=p.name;p.id=option.id;p.name=option.name;p.moves=[];state.caught=[...new Set([...state.caught,p.id])];persist();$('#modal').close();await refreshMoves(p);if(currentView==='rooms')rooms();toast(`${p.nickname} evoluiu de ${old} para ${option.name}!`);playCry(p.id)}
function selectPartner(i){if(onExpedition(state.active[i]))return toast('Este Pokémon está em expedição.');state.pokemon=state.active[i];persist();rooms();toast(`${state.pokemon.nickname} agora é seu parceiro principal.`)}
function sendToBox(i){const p=state.active[i];if(onExpedition(p))return toast('Este Pokémon está em expedição.');if(state.active.length<=1)return;if(p.uid===state.pokemon.uid)state.pokemon=state.active[i===0?1:0];state.boxes.push(...state.active.splice(i,1));persist();rooms();toast(`${p.nickname} foi enviado para a Box.`)}
function boxAction(i){if(state.active.length>=6)return toast('Os seis quartos estão ocupados.');const p=state.boxes[i];if(onExpedition(p))return toast('Este Pokémon está em expedição.');state.boxes.splice(i,1);state.active.push(p);persist();rooms();toast(`${p.nickname} ganhou um quarto.`)}
function dex(){$('#view-container').innerHTML=`<div class="view-title"><div><h1>Pokédex</h1><p>${state.caught.length} espécies capturadas · ${state.seen.length} avistadas</p></div></div><div class="dex-grid">${state.seen.map(id=>{const got=state.caught.includes(id);return`<div class="dex-card ${got?'':'unknown'}"><img src="${sprite(id)}" alt=""><b>#${String(id).padStart(4,'0')} ${POKEMON_NAMES[id]||''}</b><small>${got?'Capturado':'Avistado'}</small></div>`}).join('')}</div>`}
async function battleView(){if(!battle){const leader=LEADERS.find((l,i)=>!state.badges.includes(i)&&state.pokemon.level>=l.level-4);$('#view-container').innerHTML=`<div class="view-title"><div><h1>Centro de Batalhas</h1><p>Golpes e efetividade seguem a tipagem oficial.</p></div></div><div class="cards-grid"><article class="battle-card">${itemImg('vs-recorder')}<h2>Treinador visitante</h2><p>Adversário aleatório no seu nível.</p><button class="secondary-button" data-fight="npc">Desafiar</button></article><article class="battle-card">${itemImg('vs-seeker')}<h2>${leader?'Líder '+leader.name:'Próximo ginásio bloqueado'}</h2><p>${leader?'Insígnia '+leader.badge:'Treine mais para desbloquear.'}</p><button class="secondary-button" data-fight="leader" ${leader?'':'disabled'}>${leader?'Entrar no ginásio':'Bloqueado'}</button></article><article class="battle-card">${itemImg('tm-normal')}<h2>Golpes</h2><p>Escolha até quatro golpes aprendidos por nível.</p><button class="secondary-button" id="moves-manage">Organizar golpes</button></article></div>`;$('#view-container').onclick=e=>{const b=e.target.closest('[data-fight]');if(b)startBattle(b.dataset.fight)};$('#moves-manage').onclick=manageMoves;return}drawBattle()}
async function manageMoves(){const p=state.pokemon;toast('Consultando golpes aprendidos...');try{const moves=await movesFor(p),m=$('#modal');$('#modal-content').innerHTML=`<h2>Golpes de ${p.nickname}</h2><p>Selecione até quatro. Disponíveis no nível ${p.level}.</p><div class="move-picker">${moves.map(x=>`<label><input type="checkbox" value="${x.name}" ${(p.moves||[]).includes(x.name)?'checked':''}><b>${x.name}</b><small>${fmt(x.type)} · Poder ${x.power}</small></label>`).join('')}</div><button class="primary-button" id="save-moves">Salvar golpes</button>`;m.showModal();$('#save-moves').onclick=()=>{const picked=[...m.querySelectorAll('input:checked')].map(x=>x.value);if(!picked.length||picked.length>4)return toast('Escolha entre um e quatro golpes.');p.moves=picked;persist();m.close();toast('Golpes atualizados.') }}catch{toast('Não foi possível carregar os golpes.') }}
async function startBattle(type){const p=state.pokemon;if(onExpedition(p))return toast('Seu parceiro está em expedição.');if(p.sleepingSince)return toast('Seu parceiro está dormindo.');if(type==='leader')return chooseGymTeam();launchBattle(type,[p])}
function chooseGymTeam(){const eligible=state.active.filter(p=>!p.sleepingSince&&!onExpedition(p)),m=$('#modal');$('#modal-content').innerHTML=`<h2>Equipe do ginásio</h2><p>Escolha de um a três Pokémon. Eles entrarão na ordem selecionada.</p><div class="gym-team-picker">${eligible.map((p,i)=>`<label><input type="checkbox" value="${p.uid}" ${i===0?'checked':''}><img src="${spriteFor(p)}" alt=""><b>${p.nickname}</b><small>Nv. ${p.level}</small></label>`).join('')}</div><button class="primary-button" id="confirm-gym-team">Entrar com a equipe</button>`;m.showModal();m.querySelectorAll('input').forEach(input=>input.onchange=()=>{const checked=[...m.querySelectorAll('input:checked')];if(checked.length>3){input.checked=false;toast('Escolha no máximo três Pokémon.')}});$('#confirm-gym-team').onclick=()=>{const ids=[...m.querySelectorAll('input:checked')].map(x=>x.value);if(!ids.length)return toast('Escolha pelo menos um Pokémon.');const team=ids.map(id=>state.active.find(p=>p.uid===id)).filter(Boolean);m.close();launchBattle('leader',team)}}
async function launchBattle(type,team){toast('Preparando a batalha...');const lead=team[0];let leaderIndex=null,leader=null,specs;if(type==='leader'){leaderIndex=LEADERS.findIndex((l,i)=>!state.badges.includes(i)&&state.pokemon.level>=l.level-4);if(leaderIndex<0)return toast('Nenhum ginásio disponível agora.');leader=LEADERS[leaderIndex];specs=leader.team.map(([id,level])=>({id,level}))}else{const id=chooseWild();specs=[{id,level:Math.max(3,lead.level+Math.floor(Math.random()*5)-2)}]}try{const[fighters,enemies]=await Promise.all([Promise.all(team.map(async p=>{const[data,all]=await Promise.all([pokemon(p.id),movesFor(p)]);if(!p.moves?.length)p.moves=all.slice(-4).map(x=>x.name);let selected=all.filter(x=>p.moves.includes(x.name)).slice(0,4);if(!selected.length)selected=all.slice(-4);return{p,data,moves:selected,hp:100}})),Promise.all(specs.map(async spec=>{const[data,moves]=await Promise.all([pokemon(spec.id),movesFor(spec)]);return{...spec,data,moves:moves.slice(-4),hp:100}}))]);battle={type,leaderIndex,leader,team:fighters,playerIndex:0,enemyTeam:enemies,enemyIndex:0,log:type==='leader'?`${leader.name} aceitou o desafio!`:'A batalha começou!',busy:false};drawBattle();playCry(currentEnemy().id)}catch{toast('Não foi possível preparar a batalha.')}}
const currentFighter=()=>battle.team[battle.playerIndex];
const currentEnemy=()=>battle.enemyTeam[battle.enemyIndex];
function drawBattle(){const slot=currentFighter(),p=slot.p,e=currentEnemy();$('#view-container').innerHTML=`<div class="view-title"><div><h1>${battle.type==='leader'?`Ginásio · ${battle.leader.name}`:'Batalha'}</h1><p>${slot.data.types.map(fmt).join(' / ')} vs ${e.data.types.map(fmt).join(' / ')}</p></div><span>Rival ${battle.enemyIndex+1}/${battle.enemyTeam.length}</span></div><div class="battle-team">${battle.team.map((x,i)=>`<div class="${i===battle.playerIndex?'active':''} ${x.hp<=0?'fainted':''}"><img src="${spriteFor(x.p)}" alt=""><small>${x.p.nickname}</small><b>${Math.round(x.hp)} HP</b></div>`).join('')}</div>${battle.enemyTeam.length>1?`<div class="enemy-team">${battle.enemyTeam.map((x,i)=>`<div class="${i===battle.enemyIndex?'active':''} ${x.hp<=0?'fainted':''}"><img src="${sprite(x.id)}" alt=""><small>${x.data.name}</small></div>`).join('')}</div>`:''}<div class="battle-arena"><div class="fighter"><h3>${p.shiny?'★ ':''}${p.nickname} · Nv. ${p.level}</h3><div class="hp"><div class="stat-track"><div class="stat-fill" style="width:${slot.hp}%"></div></div></div><img src="${spriteFor(p)}" alt="${p.nickname}"></div><div class="fighter"><h3>${e.data.name} · Nv. ${e.level}</h3><div class="hp"><div class="stat-track"><div class="stat-fill" style="width:${e.hp}%"></div></div></div><img src="${sprite(e.id)}" alt="adversário"></div></div><div class="battle-log">${battle.log}</div><div class="move-buttons">${slot.moves.map((m,i)=>`<button class="move-button type-${m.type}" data-move="${i}"><b>${m.name}</b><small>${fmt(m.type)} · ${m.power}</small></button>`).join('')}</div><button class="secondary-button" id="flee">Recuar</button>`;$('#view-container').onclick=ev=>{const b=ev.target.closest('[data-move]');if(b)attack(+b.dataset.move)};$('#flee').onclick=()=>{battleAftercare(false);battle=null;persist();battleView()}}
async function effectiveness(move,defTypes){const chart=await typeChart(move.type);let mult=1;for(const t of defTypes){if(chart.none.includes(t))mult*=0;else if(chart.double.includes(t))mult*=2;else if(chart.half.includes(t))mult*=.5}return mult}
const effectText=m=>m===0?'Sem efeito!':m>=4?'Extremamente efetivo!':m>1?'Super efetivo!':m<1?'Não foi muito efetivo...':'';
async function attack(i){if(battle.busy)return;battle.busy=true;const slot=currentFighter(),enemy=currentEnemy(),p=slot.p,move=slot.moves[i],status=move.damageClass==='status'||move.power===0,mult=status?1:await effectiveness(move,enemy.data.types),dmg=status?0:(mult?Math.max(2,Math.round((move.power/5+p.level*1.5+Math.random()*8)*mult)):0);enemy.hp=clamp(enemy.hp-dmg);battle.log=`${p.nickname} usou ${move.name}! ${status?'Golpe de status.':`${effectText(mult)} ${dmg} de dano.`}`;if(enemy.hp<=0)return enemyDefeated();drawBattle();setTimeout(async()=>{const active=currentFighter(),e=currentEnemy(),em=e.moves[Math.floor(Math.random()*e.moves.length)]||{name:'Tackle',type:'normal',power:40,damageClass:'physical'},enemyStatus=em.damageClass==='status'||em.power===0,m=enemyStatus?1:await effectiveness(em,active.data.types),d=enemyStatus?0:Math.max(0,Math.round((em.power/6+e.level+Math.random()*7)*m));active.hp=clamp(active.hp-d);battle.log=`${e.data.name} usou ${em.name}! ${enemyStatus?'Golpe de status.':`${effectText(m)} ${d} de dano.`}`;battle.busy=false;if(active.hp<=0){active.p.health=clamp(active.p.health-15);const next=battle.team.findIndex((x,n)=>n>battle.playerIndex&&x.hp>0);if(next>=0){battle.playerIndex=next;battle.log+=` ${battle.team[next].p.nickname}, eu escolho você!`;persist();drawBattle();playCry(battle.team[next].p.id)}else{gainXp(12);battleAftercare(false);persist();toast('Sua equipe perdeu. Fome, felicidade e higiene diminuíram.');battle=null;battleView()}}else drawBattle()},650)}
function enemyDefeated(){const defeated=currentEnemy();if(battle.enemyIndex<battle.enemyTeam.length-1){battle.enemyIndex++;battle.busy=false;battle.log=`${defeated.data.name} foi derrotado! ${currentEnemy().data.name}, eu escolho você!`;drawBattle();playCry(currentEnemy().id);return}winBattle()}
function battleAftercare(won){for(const slot of battle.team){const p=slot.p;p.hunger=clamp(p.hunger-18);p.happiness=clamp(p.happiness-(won?12:20));p.hygiene=clamp(p.hygiene-15);p.friendship=clamp((p.friendship??70)+(won?4:-5))}}
function winBattle(){const gym=battle.type==='leader',base=battle.enemyTeam.reduce((n,e)=>n+e.data.baseExperience+e.level*4,0),factor=.85+Math.random()*.3,reward=gym?battle.leader.reward:{coins:Math.round(base*.28*factor),xp:Math.round(base*.36*factor),items:{}};state.coins+=reward.coins;gainXp(reward.xp);for(const[id,q]of Object.entries(reward.items||{}))state.inventory[id]=(state.inventory[id]||0)+q;battleAftercare(true);state.pokemon.ev+=1+(state.furniture.includes('treadmill')?1:0);progressMissions('battleWin');if(gym){state.badges=[...new Set([...state.badges,battle.leaderIndex])];progressMissions('gym',{gym:battle.leaderIndex})}else progressMissions('npcWin');persist();const message=`Vitória! +${reward.xp} XP e +${reward.coins} PokéCoins${reward.items?.['master-ball']?' · Master Ball obtida!':''}`;battle=null;toast(message);battleView()}
function showHelp(){const m=$('#modal');$('#modal-content').innerHTML=`<h2>Guia do treinador</h2><div class="help-grid"><section><b>Cuidados e sono</b><p>Fome, energia, felicidade e higiene caem continuamente. Dormindo, o desgaste cai pela metade e a energia se recupera: até 8h, ou 4h com a cama melhorada.</p></section><section><b>Aparições</b><p>Espécies têm raridades fixas. Horário, clima e temperatura alteram as chances.</p></section><section class="weather-guide"><b>Tabela de clima</b><table><thead><tr><th>Condição</th><th>Tipos favorecidos</th></tr></thead><tbody><tr><td>Céu limpo/dia</td><td>Planta, Fogo, Voador</td></tr><tr><td>Nublado</td><td>Normal, Lutador, Fada</td></tr><tr><td>Chuva</td><td>Água, Elétrico, Inseto</td></tr><tr><td>Tempestade</td><td>Elétrico, Dragão, Água</td></tr><tr><td>Neblina</td><td>Fantasma, Sombrio, Psíquico</td></tr><tr><td>Noite</td><td>Fantasma, Sombrio, Venenoso</td></tr><tr><td>Abaixo de 20°C</td><td>Gelo e Aço</td></tr></tbody></table></section><section><b>Shiny</b><p>Cada nova aparição tem chance de 1 em 200 de ser shiny. A característica permanece após a captura.</p></section><section><b>Captura</b><p>Escolha a Pokébola na bandeja. Verde indica fácil, amarelo médio e vermelho difícil. A berry da tipagem correta melhora bastante a chance.</p></section><section><b>Incenso</b><p>Ative na Mochila. Por 30 minutos, visitantes podem surgir em intervalos bem menores.</p></section><section><b>Quartos e Boxes</b><p>Até seis Pokémon ficam ativos. Móveis comprados aparecem no quarto e podem ser reposicionados pelo botão “Mover móveis”.</p></section><section><b>Minigames</b><p>Gastam energia e ficam bloqueados sem energia suficiente ou enquanto o parceiro dorme.</p></section><section><b>Batalhas</b><p>NPCs acompanham o nível do parceiro. Em ginásios, escolha uma equipe de até três Pokémon ativos.</p></section></div>`;if(!m.open)m.showModal()}
function showChangelog(){const m=$('#modal');$('#modal-content').innerHTML=`<h2>Changelog</h2><div class="changelog"><section><b>v3.1 · Quartos e equipes</b><p>Móveis menores e reposicionáveis, poções, tabela climática, captura circular, contadores maiores, incenso corrigido, equipe de ginásio e novo decaimento de status.</p></section><section><b>v3.0 · Mundo vivo</b><p>Raridade fixa por espécie, aparições por clima/horário, Gelo abaixo de 20°C, shiny 1/200, incenso, captura visual, gritos oficiais, ajuda, cenários e móveis visíveis.</p></section><section><b>v2.3 · Tempo & Sono</b><p>Recuperação offline de energia e passagem contínua dos status.</p></section><section><b>v2.2 · PokéMart</b><p>Categorias, itens evolutivos, berries por tipagem e móveis com bônus.</p></section><section><b>v2.1 · Jornadas</b><p>Continuar/nova jornada, apelidos e recuperação das Boxes.</p></section></div>`;if(!m.open)m.showModal()}
function settings(){const m=$('#modal');$('#modal-content').innerHTML=`<h2>Configurações</h2><div class="settings-list"><p>O jogo salva automaticamente neste navegador.</p><div class="location-notice"><img src="${itemSprite('town-map')}" alt=""> Recomendamos permitir a localização para clima e ciclo local mais precisos.</div><button class="secondary-button" id="toggle-sound">Gritos Pokémon: ${state.soundEnabled?'ligados':'desligados'}</button><button class="secondary-button" id="weather-refresh">Atualizar tempo local</button><button class="secondary-button" id="open-help">Abrir ajuda</button><button class="secondary-button" id="open-changelog">Ver changelog</button><button class="danger-button" id="reset-save">Apagar progresso e recomeçar</button></div>`;m.showModal();$('#toggle-sound').onclick=()=>{state.soundEnabled=!state.soundEnabled;persist();settings()};$('#weather-refresh').onclick=()=>{updateWeather();m.close();toast('Buscando o tempo da sua região...')};$('#open-help').onclick=showHelp;$('#open-changelog').onclick=showChangelog;$('#reset-save').onclick=()=>{if(confirm('Apagar todo o progresso?')){clear();location.reload()}}}
const legacyHelp=showHelp;showHelp=function(){legacyHelp();$('#modal-content').insertAdjacentHTML('beforeend',`<section><b>Perfil e títulos</b><p>Escolha seu nome no Perfil e equipe títulos desbloqueados. Títulos acompanham tipagens, coleção, capturas, batalhas, cuidados, ginásios, arcade e expedições.</p></section><section><b>Evoluções do Eevee</b><p>Vaporeon, Jolteon, Flareon, Leafeon e Glaceon usam pedras. Espeon e Umbreon exigem nível 25, amizade 80 e o horário correto. Sylveon exige nível 25, amizade 80 e golpe Fada equipado.</p></section><section><b>Eventos e expedições</b><p>Escolha um evento e um Pokémon com pelo menos 30 de saúde e energia. A previsão considera nível, tipos e status. A expedição dura 2 horas, continua offline e pode fracassar.</p></section><section><b>Centro de Resgate</b><p>Cada sucesso pode trazer até cinco Pokémon. Todos permanecem seguros para tentativas individuais com berries e Pokébolas. O limite é 20 resgatados.</p></section>`)};
const legacyChangelog=showChangelog;showChangelog=function(){legacyChangelog();$('#modal-content .changelog').insertAdjacentHTML('afterbegin',`<section><b>v5.0 · Identidade & Expedições</b><p>Nome do treinador, títulos equipáveis e retroativos, rotas completas do Eevee, Tempestade de Gelo, Emergência no Laboratório, previsão de risco, expedições offline de 2 horas e Centro de Resgate.</p></section>`)};
const helpV5=showHelp;showHelp=function(){helpV5();const incense=[...$('#modal-content').querySelectorAll('section')].find(s=>s.querySelector('b')?.textContent==='Incenso');if(incense)incense.querySelector('p').textContent='Ative na Mochila. Por 1 hora, uma nova aparição é gerada a cada 5 minutos.'};
const pokemonStatusWithoutTypes=pokemonStatus;
pokemonStatus=async uid=>{const p=findOwned(uid);if(p&&!Array.isArray(p.types))try{p.types=(await pokemon(p.id)).types;persist()}catch{p.types=[]}await pokemonStatusWithoutTypes(uid);const head=$('#modal-content .pokemon-status-head>div');if(head&&p&&!head.querySelector('.type-icons'))head.insertAdjacentHTML('beforeend',typeIcons(p.types))};
const roomsWithoutTypes=rooms;
rooms=async()=>{roomsWithoutTypes();await hydrateOwnedTypes();if(currentView!=='rooms')return;document.querySelectorAll('[data-statusuid]').forEach(button=>{const p=findOwned(button.dataset.statusuid),card=button.closest('.poke-room,.box-mon');if(card&&p&&!card.querySelector('.type-icons'))card.querySelector('small')?.insertAdjacentHTML('afterend',typeIcons(p.types))})};
const profileWithoutOwnedFilter=profileView;
profileView=async()=>{const ownedOnly=titleFilter==='Meus títulos';if(ownedOnly)titleFilter='Todos';await profileWithoutOwnedFilter();if(currentView!=='profile')return;if(ownedOnly)titleFilter='Meus títulos';const filters=$('.title-filters');if(!filters)return;filters.insertAdjacentHTML('afterbegin',`<button class="${ownedOnly?'active':''}" data-title-filter="Meus títulos">Meus títulos</button>`);if(ownedOnly){filters.querySelector('[data-title-filter="Todos"]')?.classList.remove('active');document.querySelectorAll('.title-card.locked').forEach(card=>card.remove())}};
$('#modal-close').onclick=()=>$('#modal').close();setInterval(()=>{updateDailyButton();updateSleepTimer();updateExpeditionTimer()},1000);setInterval(()=>{if(state){applyOffline(state);generateOfflineEncounters();persist();if(currentView==='home'&&!furnitureEditing)home()}},30000);window.addEventListener('beforeunload',()=>state&&persist());
showTitle();
